const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(data[0], 10);

let ans = 0;
let p1 = 0; // posição (1-indexada) do 1 mais recente
let p2 = 0; // posição do 1 anterior a esse

for (let i = 1; i <= n; i++) {
  if (data[i] === '1') {
    // o 1 em p1 tem à esquerda (p1 - p2) escolhas de l
    // e à direita (i - p1) escolhas de r (até antes deste novo 1)
    ans += (p1 - p2) * (i - p1);
    p2 = p1;
    p1 = i;
  }
}

// último 1 da lista: seções à direita vão até o fim (n + 1 - p1) escolhas
ans += (p1 - p2) * (n + 1 - p1);

console.log(ans);
